CoworkBilling.Chargeback Prepaid Share %.dax:
// Tenant-wide, so every cost centre is charged at the same blended rate and the
// charges add up to Cowork Total Cost. The period and the Cowork/WorkIQ toggle
// still apply.
VAR Used =
    CALCULATE(
        [Cowork Total Credits Used],
        REMOVEFILTERS( 'SpendingPolicy' ),
        REMOVEFILTERS( 'Org' ),
        REMOVEFILTERS( 'Group By' ),
        REMOVEFILTERS( 'CoworkBilling' )
    )
RETURN
    DIVIDE( MIN( Used, [Cowork Prepaid Balance] ), Used )

CoworkBilling.Allocated Credits.dax:
// A person's weeks under an earlier policy follow them to their current one
// (CoworkBilling[SpendingPolicyId]), so the cost centres add up to the tenant
// total, as in the app's Chargeback view.
VAR People = VALUES( 'CoworkBilling'[UserPrincipalName] )
RETURN
    IF( NOT ISEMPTY( People ),
        CALCULATE(
            [Cowork Total Credits Used],
            REMOVEFILTERS( 'SpendingPolicy' ),
            TREATAS( People, 'CoworkBilling'[UserPrincipalName] )
        )
    )

CoworkBilling.Cowork Prepaid Used.dax:
// MIN coerces BLANK to a number, so a group with no Cowork users
// reported 0 prepaid credits and kept its row on the Cost page at
// $0 - while the Consumption page correctly dropped it.
// Credits Used already separates "no users" (BLANK) from "users
// who spent nothing" (0), so defer to it.
VAR Used = [Cowork Total Credits Used]
RETURN
	IF( NOT ISBLANK( Used ), MIN( Used, [Cowork Prepaid Balance] ) )

CoworkBilling.Cowork PAYG Credits.dax:
// Same coercion as Cowork Prepaid Used: BLANK - 0 is 0, and MAX
// then returns a real zero rather than passing the blank through.
VAR Used = [Cowork Total Credits Used]
RETURN
	IF( NOT ISBLANK( Used ),
		MAX( 0, Used - [Cowork Prepaid Balance] ) )

CreditsWeekly.Growth Applied %.dax:
// Branch on the scenario name, so no selection and the explicit
// "Fitted from history" option behave identically.
VAR Chosen = SELECTEDVALUE( 'Growth Scenario'[Scenario], "Fitted from history" )
VAR Rate   = SELECTEDVALUE( 'Growth Scenario'[Rate] )
RETURN
    IF( Chosen = "Fitted from history", COALESCE( [Implied Monthly Growth %], 0 ), Rate )

Credit Consumption (Tenant).Studio Prepa.dax:
// KEEPFILTERS matters here. Without it, FILTER(ALL(Usage_Date), ...)
// replaces the date context supplied by a chart axis, so every point
// returned the whole-period total and the trend line rendered flat.
// KEEPFILTERS intersects the period window with the axis date instead.
VAR FromDate = [Studio Period Start]
RETURN
CALCULATE(
    SUM( 'Credit Consumption (Tenant)'[Prepaid_Consumed_Quantity] ),
    KEEPFILTERS(
        FILTER(
            ALL( 'Credit Consumption (Tenant)'[Usage_Date] ),
            'Credit Consumption (Tenant)'[Usage_Date] >= FromDate
        )
    )
)

Credit Consumption (Tenant).Studio PAYG.dax:
// See Prepaid Consumed: KEEPFILTERS keeps the chart axis date intact.
VAR FromDate = [Studio Period Start]
RETURN
CALCULATE(
    SUM( 'Credit Consumption (Tenant)'[Pay_as_you_go_Consumed_Quantity] ),
    KEEPFILTERS(
        FILTER(
            ALL( 'Credit Consumption (Tenant)'[Usage_Date] ),
            'Credit Consumption (Tenant)'[Usage_Date] >= FromDate
        )
    )
)

Credit Consumption (Tenant).Studio Entit.dax:
// Entitlement is a stock, not a flow. The export restates it on every
// daily row, so a plain SUM multiplies it by the number of days observed.
// Read the latest value per environment instead.
SUMX(
    VALUES( 'Credit Consumption (Tenant)'[Environment_Name] ),
    VAR LastDay = CALCULATE( MAX( 'Credit Consumption (Tenant)'[Usage_Date] ) )
    RETURN
        CALCULATE(
            MAX( 'Credit Consumption (Tenant)'[Entitled_Quantity] ),
            'Credit Consumption (Tenant)'[Usage_Date] = LastDay
        )
)

// Only an environment that holds an entitlement can consume one. The
// unscoped version divided tenant-wide prepaid consumption (21,812) by
// a single environment's grant (5,000) and reported 436%.
VAR PerEnv =
    ADDCOLUMNS(
        VALUES( 'Studio Environment'[Environment Name] ),
        "@ent",  [Studio Entitled Capacity],
        "@used", [Studio Prepaid Consumed]
    )
VAR Entitled = FILTER( PerEnv, [@ent] > 0 )
RETURN
    DIVIDE( SUMX( Entitled, [@used] ), SUMX( Entitled, [@ent] ) )

Credit Consumption (Tenant).Environments.dax:
COUNTROWS(
    FILTER(
        VALUES( 'Credit Consumption (Tenant)'[Environment_Name] ),
        [Studio Entitled Capacity] = 0 && CALCULATE( [Studio Prepaid Consumed] ) > 0
    )
)

Credit Consumption (Tenant).Studio Entit.dax:
// Scoped to entitled environments for the same reason as Entitlement
// Utilisation %: subtracting tenant-wide consumption from one
// environment's grant went negative and clamped to zero.
VAR PerEnv =
    ADDCOLUMNS(
        VALUES( 'Studio Environment'[Environment Name] ),
        "@ent",  [Studio Entitled Capacity],
        "@used", [Studio Prepaid Consumed]
    )
VAR Entitled = FILTER( PerEnv, [@ent] > 0 )
RETURN
    MAX( 0, SUMX( Entitled, [@ent] - [@used] ) )

Credit Consumption (Agent).Agent Credit.dax:
// Must clear the Agent Bridge as well as the fact table: the visual groups by
// the bridge, so filtering only the fact table leaves the denominator scoped
// to a single agent and every share reads near 100%.
DIVIDE(
    [Studio Consumed Credits (Agent)],
    CALCULATE(
        [Studio Consumed Credits (Agent)],
        ALLSELECTED( 'Credit Consumption (Agent)' ),
        ALLSELECTED( 'Agent Bridge' )
    )
)

Credit Consumption (Agent).Agents with N.dax:
COUNTROWS(
    FILTER(
        VALUES('Credit Consumption (Agent)'[Agent_Name]),
        CALCULATE( [Studio Consumed Credits (Agent)] ) = 0
    )
)

Credit Consumption (User).User Credit Sh.dax:
// Clears the Agent Bridge too, so the denominator stays the whole selection
// even when the visual is grouped by a bridged dimension.
DIVIDE(
    [Studio Total Credits Used],
    CALCULATE(
        [Studio Total Credits Used],
        ALLSELECTED( 'Credit Consumption (User)' ),
        ALLSELECTED( 'Agent Bridge' )
    )
)

Studio Period.Studio Period Start.dax:
// WindowDays rather than Days, for readability. Note DAYS is in fact
// a legal VAR name - probed against the engine - whereas DATE,
// EARLIER and EARLIEST are not. An earlier version of this comment
// claimed DAY was the problem; it is not.
VAR WindowDays = [Studio Period Days]
VAR Latest =
    CALCULATE(
        MAX( 'Credit Consumption (Tenant)'[Usage_Date] ),
        REMOVEFILTERS( 'Credit Consumption (Tenant)'[Usage_Date] )
    )
RETURN
    IF(
        WindowDays = 0,
        CALCULATE(
            MIN( 'Credit Consumption (Tenant)'[Usage_Date] ),
            REMOVEFILTERS( 'Credit Consumption (Tenant)'[Usage_Date] )
        ),
        Latest - WindowDays + 1
    )

Agent Action Group.Credits in Action.dax:
// The blank test lives inside FILTER rather than in an IF around it,
// because IF cannot return a table expression here.
VAR Lbl = SELECTEDVALUE( 'Agent Action Group'[Action] )
VAR Scoped =
    FILTER(
        VALUES( 'Credit Consumption (Agent)'[Agent_Name] ),
        ISBLANK( Lbl ) || [Agent Action] = Lbl
    )
RETURN
    SUMX( Scoped, [Studio Consumed Credits (Agent)] )

GitHub Usage.GHCP Credits Used.dax:
// KEEPFILTERS, not a bare FILTER. Without it the period window REPLACES the
// date context a chart axis supplies, so every point returns the whole-period
// total and the trend renders flat.
VAR FromDate = [GHCP Period Start]
RETURN
CALCULATE(
    SUM( 'GitHub Usage'[Credits] ),
    KEEPFILTERS(
        FILTER(
            ALL( 'GitHub Usage'[Usage_Date] ),
            'GitHub Usage'[Usage_Date] >= FromDate
        )
    )
)

AzureAiSpend.Foundry Cost.dax:
// The period gate lives here rather than on each derived measure:
// Input Cost, Output Cost, Output Share, Cost per 1M, Daily Run
// Rate and Cost /mo all descend from this one, so they inherit it.
//
// KEEPFILTERS on the date predicate matters. A bare
// FILTER(ALL(UsageDate), ...) REPLACES the date context a chart
// axis supplies, so every point on the weekly trend would return
// the whole-period total and the line would render flat.
VAR FromDate = [Foundry Period Start]
RETURN
CALCULATE(
    SUM( 'AzureAiSpend'[Cost] ),
    KEEPFILTERS( 'AzureAiSpend'[ServiceName] = "Foundry Models" ),
    KEEPFILTERS(
        FILTER( ALL( 'AzureAiSpend'[UsageDate] ),
                'AzureAiSpend'[UsageDate] >= FromDate )
    )
)

Foundry Period.Foundry Period Start.dax:
// FirstDay / LastDay, because EARLIEST is a DAX function and a VAR
// of that name collides rather than shadows. The parse fails, this
// measure drops to state 5, and the sixteen measures downstream
// all report "refers to a measure which has an error" - none of
// them naming the real fault. EARLIEST did exactly that here on
// the first build of this table.
//
// Probed against the engine: DATE, EARLIER and EARLIEST are
// rejected; DAY and DAYS are fine. WindowDays is named for
// clarity, not necessity.
VAR WindowDays = [Foundry Period Days]
VAR LastDay =
    CALCULATE(
        MAX( 'AzureAiSpend'[UsageDate] ),
        REMOVEFILTERS( 'AzureAiSpend'[UsageDate] )
    )
VAR FirstDay =
    CALCULATE(
        MIN( 'AzureAiSpend'[UsageDate] ),
        REMOVEFILTERS( 'AzureAiSpend'[UsageDate] )
    )
RETURN IF( WindowDays = 0, FirstDay, LastDay - WindowDays + 1 )
